CREATE OR REPLACE FUNCTION private.institution_member_not_org_member()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (select 1 from public.client_accounts a
             join public.organization_memberships m on m.organization_id = a.organization_id
